  ui_story_5025_50253301_101_dialog_content = "Excellent. Call me when the stuff arrive so I can take a look.",
  ui_story_5025_50253301_102_dialog_content = "Just in case you bought something you shouldn't have...",
  ui_story_5025_50253301_103_dialog_content = "There's no need, I promise you I didn't make any mistakes.",
  ui_story_5025_50253301_104_dialog_content = "<size=30>Hmm... She's so strict when it comes to accounts... It should probably be an account book after all...</size>",
  ui_story_5025_50253301_105_dialog_content = "What did you say? I think I just heard \"account book\"...",
