  ui_story_5025_50253301_115_dialog_content = "Which do you like more, bookkeeping, making plans, studying recipes, or collecting drawings and stickers?",
  ui_story_5025_50253301_116_dialog_content = "Err... Why do you ask?",
  ui_story_5025_50253301_117_dialog_content = "It's fine if you like them all, but I was wondering if you had a preference!",
  ui_story_5025_50253301_118_dialog_content = "Err... I'm completely lost.",
