  ui_story_5025_50253301_122_dialog_content = "Even if I did, it would've been something absolutely necessary!",
  ui_story_5025_50253301_123_dialog_content = "So you did...",
  ui_story_5025_50253301_124_dialog_content = "Delivery! Coo! Could anyone please sign for it?",
  ui_story_5025_50253301_125_dialog_content = "Ah! Dove. Over here!",
  ui_story_5025_50253301_126_dialog_content = "Huff, huff... I didn't expect one little diary to be this big and heavy...",
  ui_story_5025_50253301_127_dialog_content = "If I'd known, I so wouldn't have agreed to deliver this.",
