  ui_story_5025_50253301_133_dialog_content = "Hey! I'm a good cook, okay?",
  ui_story_5025_50253301_134_dialog_content = "<size=30>She got a new notebook already...</size>",
  ui_story_5025_50253301_135_dialog_content = "<size=30>Then the one I meant to buy wouldn't be of much use...</size>",
  ui_story_5025_50253301_136_dialog_content = "Huh? PlayerName, did you say something?",
  ui_story_5025_50253301_137_dialog_content = "Ah... Sorry, excuse me for a second.",
  ui_story_5025_50253301_138_dialog_content = "The delivery guys are coming, I need to talk to them quickly...",
  ui_story_5025_50253301_139_dialog_content = "Argh! So many things to deliver. I'm exhausted.",
  ui_story_5025_50253301_140_dialog_content = "The pay better be good this time... Are we getting a decent amount? Like for real?",
  ui_story_5025_50253301_141_dialog_content = "Thank you for choosing the Courier Union.",
  ui_story_5025_50253301_142_dialog_content = "Heheh. Your service will be paid by this very generous client of mine. You should probably thank him.",
  ui_story_5025_50253301_143_dialog_content = "Sheol, good to see you. Listen...",
  ui_story_5025_50253301_144_dialog_content = "The notebook... I don't need anymore. Vice got one herself already.",
  ui_story_5025_50253301_145_dialog_content = "Don't need it anymore? Are you returning this?!",
  ui_story_5025_50253301_149_dialog_content = "Why are you giving up on gifting her this?",
  ui_story_5025_50253301_150_dialog_content = "Even if she's got a new one, you can still buy her a gift.",
  ui_story_5025_50253301_151_dialog_content = "The gift represents your intentions. It's about your efforts to make her happy.",
  ui_story_5025_50253301_152_dialog_content = "When you struggled to pick a suitable gift for her, I felt how much you care about her.",
  ui_story_5025_50253301_153_dialog_content = "I'm sure she'll feel it as well.",
  ui_story_5025_50253301_154_dialog_content = "Hmm, I know... Actually I've already decided.",
  ui_story_5025_50253301_155_dialog_content = "Oh? And I thought this would upset you. But you look just fine.",
  ui_story_5025_50253301_155X1_dialog_content = "To be completely honest with you, I'm a little upset...",
  ui_story_5025_50253301_155X2_dialog_content = "I wish I'd just told her directly that I was planning on getting her a new diary.",
  ui_story_5025_50253301_156_dialog_content = "So... What's your plan now?",
  ui_story_5025_50253301_157_dialog_content = "Err... I'll take one account book, one planner, one sketchbook, and one schedule book!",
  ui_story_5025_50253301_158_dialog_content = "A few notebooks won't break the bank, after all. They'll all be used sooner or later.",
  ui_story_5025_50253301_159_dialog_content = "I'll give her several so she can use whichever she likes whenever she wants.",
  ui_story_5025_50253301_160_dialog_content = "Haha. A very generous client you are!",
  ui_story_5025_50253301_161_dialog_content = "Phew... Finally...",
  ui_story_5025_50253301_162_dialog_content = "Should have done it this way in the first place... I've been quite silly.",
  ui_story_5025_50253301_163_dialog_content = "I just need to figure out how to hand her this pile of notebooks...",
  ui_story_5025_50253301_164_dialog_content = "Vice... Hmm? Where did she go?",
  ui_story_5025_50253301_165_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5025_50253301_166_dialog_content = "Where did these ribbons and paper crackers come from?",
  ui_story_5025_50253301_167_dialog_content = "These are small gifts from the Rediesel Wrench. I thought they'd be perfect for a special occasion...",
  ui_story_5025_50253301_168_dialog_content = "Right, you just said the courier came. Everything you bought was delivered?",
  ui_story_5025_50253301_169_dialog_content = "Yep, it's all settled... But what's the special occasion today?",
  ui_story_5025_50253301_170_dialog_content = "Don't tell me you're celebrating my successful shopping trip...",
  ui_story_5025_50253301_170X_dialog_content = "Ah-ha-ha. If we must have a reason to celebrate, how about the completion of my travel and adventure journal?",
  ui_story_5025_50253301_171_dialog_content = "Hmm? That's a bit random, don't you think?",
  ui_story_5025_50253301_172_dialog_content = "Hmm... Err... How should I put this?",
  ui_story_5025_50253301_173_dialog_content = "I realized my diary book was running out of pages.",
  ui_story_5025_50253301_174_dialog_content = "So I decided to finish it with something special...",
  ui_story_5025_50253301_175_dialog_content = "I thought about it a lot.",
  ui_story_5025_50253301_176_dialog_content = "I started keeping this journal after we met.",
  ui_story_5025_50253301_177_dialog_content = "Your name appears in the book more often than anyone else's.",
  ui_story_5025_50253301_178_dialog_content = "Since I started this diary to record things about you, it only makes sense to finish it with something about you.",
  ui_story_5025_50253301_178X_dialog_content = "So I decided to do something for you as a thank-you for this very special journey.",
  ui_story_5025_50253301_179_dialog_content = "In short, I'm making today a special day for you and I'll record it as the last entry of my journal!",
  ui_story_5025_50253301_180_dialog_content = "Err... Okay. I think I understand now...",
  ui_story_5025_50253301_180X_dialog_content = "What do we do then? How should we celebrate?",
  ui_story_5025_50253301_181_dialog_content = "You won't get a scolding for today's splurging.",
  ui_story_5025_50253301_182_dialog_content = "I planned a feast for you but...",
  ui_story_5025_50253301_183_dialog_content = "A feast?!",
  ui_story_5025_50253301_184_dialog_content = "What's with that frightened look on your face?",
  ui_story_5025_50253301_185_dialog_content = "I want to prove that I really can cook. What's wrong with that?",
  ui_story_5025_50253301_186_dialog_content = "Nothing... Nothing's wrong... This is totally fine.",
  ui_story_5025_50253301_187_dialog_content = "Anyway, I changed my mind because I've got a better idea!",
  ui_story_5025_50253301_188_dialog_content = "What is that?",
  ui_story_5025_50253301_189_dialog_content = "I'll get everyone to write a message for you!",
  ui_story_5025_50253301_191_dialog_content = "A message for me?",
  ui_story_5025_50253301_192_dialog_content = "Yep, all about you...",
  ui_story_5025_50253301_193_dialog_content = "Heheh. You and PlayerName are a funny pair. He just came not long ago...",
  ui_story_5025_50253301_194_dialog_content = "As for the reason... I can't tell you yet.",
  ui_story_5025_50253301_195_dialog_content = "All I can say is... The care and consideration you have towards each other seems nice.",
  ui_story_5025_50253301_196_dialog_content = "Yes, I completely agree.",
  ui_story_5025_50253301_197_dialog_content = "So about the message... Can I just write something simple? Like...",
  ui_story_5025_50253301_198_dialog_content = "\"Thank you for your help, PlayerName.\"",
  ui_story_5025_50253301_199_dialog_content = "My tuwn. I wanna write something too!",
  ui_story_5025_50253301_200_dialog_content = "I want to say it was weally fun to pway with PlayerName.",
  ui_story_5025_50253301_201_dialog_content = "I wish Gwammy and Sanki could join us next time!",
  ui_story_5025_50253301_201X_dialog_content = "Yeah, that would be nice.",
  ui_story_5025_50253301_202_dialog_content = "A message for PlayerName?",
  ui_story_5025_50253301_203_dialog_content = "Hmm... \"That day you came to reinforce the transport station, you helped us a lot.\"",
  ui_story_5025_50253301_203X_dialog_content = "\"You are an outstanding commander.\"",
  ui_story_5025_50253301_204_dialog_content = "What are you guys up to? Did someone say \"commander\"?",
  ui_story_5025_50253301_205_dialog_content = "We're leaving messages for PlayerName. Come and write something.",
  ui_story_5025_50253301_206_dialog_content = "I don't get it. What am I supposed to write?",
  ui_story_5025_50253301_207_dialog_content = "You can thank PlayerName or something.",
  ui_story_5025_50253301_208_dialog_content = "Alright...",
  ui_story_5025_50253301_209_dialog_content = "\"You can thank PlayerName\"... Done.",
  ui_story_5025_50253301_210_dialog_content = "I want to thank PlayerName... and everyone else.",
  ui_story_5025_50253301_211_dialog_content = "I'll never forget our trip to the sea.",
  ui_story_5025_50253301_212_dialog_content = "And... I just received Paloma's reply. She was really fast this time.",
  ui_story_5025_50253301_213_dialog_content = "She said... \"I didn't expect you to reach out to me for such a trifle.\"",
  ui_story_5025_50253301_214_dialog_content = "\"But if it's for Navigator, I'll do it.\"",
  ui_story_5025_50253301_215_dialog_content = "\"He's a very nice guy. Please leave that message for me.\"",
  ui_story_5025_50253301_216_dialog_content = "A few messages are nothing!",
  ui_story_5025_50253301_217_dialog_content = "We should at least get him down here for a few more meals with the Rediesel Wrench!",
  ui_story_5025_50253301_218_dialog_content = "Brother! You mean we should invite him over.",
  ui_story_5025_50253301_219_dialog_content = "That's right. Eve is correct.",
  ui_story_5025_50253301_220_dialog_content = "Speaking of Eve, I can't thank him enough.",
  ui_story_5025_50253301_221_dialog_content = "Navigator is welcome to join the Rediesel Wrench any time. I bet he's getting sick of this line.",
  ui_story_5025_50253301_222_dialog_content = "Let me rephrase. The Rediesel Wrench will always be by PlayerName's side!",
  ui_story_5025_50253301_223_dialog_content = "Tsk... That doesn't sound good either. I need to think...",
  ui_story_5025_50253301_224_dialog_content = "I'll get all the Rediesel Wrench members here to write something. I'm sure Roy would love this...",
  ui_story_5025_50253301_225_dialog_content = "But I don't think you have enough pages there...",
  ui_story_5025_50253301_226_dialog_content = "\"To PlayerName: You are an honorable guest of the Guild and a dear friend of mine.\"",
  ui_story_5025_50253301_227_dialog_content = "\"I'll always remember the help you provided us and your kindness.\"",
  ui_story_5025_50253301_228_dialog_content = "And PlayerName's bravery.",
  ui_story_5025_50253301_229_dialog_content = "He always charges to the front to engage those Eclipsites and protect the rest of us.",
  ui_story_5025_50253301_230_dialog_content = "Too many words to say. How to keep it short?",
  ui_story_5025_50253301_231_dialog_content = "Hmm... The most important?",
  ui_story_5025_50253301_232_dialog_content = "Okay... How about this? \"I wish to celebrate New Year with you again!\"",
  ui_story_5025_50253301_233_dialog_content = "I believe Her Majesty the Queen and Novio would agree with me.",
  ui_story_5025_50253301_234_dialog_content = "... They all have so much to tell PlayerName.",
  ui_story_5025_50253301_235_dialog_content = "Indeed. We're actually receiving more replies.",
  ui_story_5025_50253301_235X1_dialog_content = "Hedy asked in her letter if she could buy PlayerName a house.",
  ui_story_5025_50253301_235X2_dialog_content = "Ah... This...",
  ui_story_5025_50253301_235X3_dialog_content = "I rejected the offer.",
  ui_story_5025_50253301_235X4_dialog_content = "Ahaha! It's a pity...",
  ui_story_5025_50253301_235X5_dialog_content = "In any case, the pages left in your diary are definitely not enough.",
  ui_story_5025_50253301_236_dialog_content = "Yeah... I guess I need a bigger notebook next time.",
  ui_story_5025_50253301_237_dialog_content = "Did you save PlayerName a line?",
  ui_story_5025_50253301_238_dialog_content = "Of course. The last words must come from PlayerName. And you haven't written anything yet.",
  ui_story_5025_50253301_239_dialog_content = "Me? Ahem... We've been together for so long. That's really not necessary...",
  ui_story_5025_50253301_240_dialog_content = "It is necessary! It's very necessary! It's your chance to spill your heart out.",
  ui_story_5025_50253301_241_dialog_content = "Because we've been together for so long, it's important for us to express our feelings.",
  ui_story_5025_50253301_242_dialog_content = "Fine, you have a point. Then...",
  ui_story_5025_50253301_243_dialog_content = [[
"Thank you for being part of my life."
"The future is long and we still have a lot of time..."]],
  ui_story_5025_50253301_244_dialog_content = "\"Let's continue our journey. —From Carleen\"",
  ui_story_5025_50253301_245_dialog_content = "This is what Carleen wanted to tell you the most.",
  ui_story_5025_50253301_246_dialog_content = "This is what you've been busy with lately...",
  ui_story_5025_50253301_247_dialog_content = "Yeah. I started by asking our friends on the Colossus to write you a message.",
  ui_story_5025_50253301_248_dialog_content = "But more and more people ended up taking part.",
  ui_story_5025_50253301_249_dialog_content = "How do you feel? Do you remember any of these events they mentioned?",
  ui_story_5025_50253301_250_option_content = "Hmm... Only some of them.",
  ui_story_5025_50253301_251_dialog_content = "Give me some more time to recollect...",
  ui_story_5025_50253301_252_dialog_content = "It's okay if you can't remember. Please continue.",
  ui_story_5025_50253301_253_dialog_content = "Old memories will come back when we see those friends again.",
  ui_story_5025_50253301_254_option_content = "Of course. I remember all of them.",
  ui_story_5025_50253301_255_dialog_content = "Since I returned to the world from underground and set out on this journey...",
  ui_story_5025_50253301_256_dialog_content = "We've experienced so much and met so many people. They're all precious memories.",
  ui_story_5025_50253301_257_dialog_content = "Yes. And more adventures and interesting people are waiting for us down the road.",
  ui_story_5025_50253301_258_dialog_content = "We'll keep journeying on together!",
  ui_story_5025_50253301_258X_dialog_content = "That's why I switched to a thicker notebook.",
  ui_story_5025_50253301_259_dialog_content = "Haha. I'm feeling a bit emotional...",
  ui_story_5025_50253301_260_dialog_content = "I'm so happy. And I'm recalling so many old memories!",
  ui_story_5025_50253301_261_dialog_content = "Sadly, my notebook wasn't big enough to keep track of everything...",
  ui_story_5025_50253301_262_dialog_content = "I'll let you see it once I get everything organized.",
  ui_story_5025_50253301_263_dialog_content = "Haha. Thank you. I can't wait!",
  ui_story_5025_50253301_264_dialog_content = "Speaking of notebooks... I've got a big box of them for you.",
  ui_story_5025_50253301_265_dialog_content = "From planners to schedule books, from account books to sketch pads, plus a bunch of looseleaf paper and bookmarks...",
  ui_story_5025_50253301_266_dialog_content = "I've got everything covered. Take your time. No rush.",
  ui_story_5025_50253301_267_dialog_content = "...",
  ui_story_5025_50253301_268_dialog_content = "Hello? Are you alright?",
  ui_story_5025_50253301_269_dialog_content = "Heheh. I'm fine... This is a very lovely surprise! I'm thrilled!",
  ui_story_5025_50253301_270_dialog_content = "I feel like our minds were in sync...",
  ui_story_5025_50253301_271_dialog_content = "The extra money you spent was on a gift for me. I almost wronged you. I'm sorry.",
  ui_story_5025_50253301_272_dialog_content = "Haha. I tried so hard to explain myself without spoiling this surprise.",
  ui_story_5025_50253301_273_dialog_content = "I know you're always struggling to keep our expenses on the Colossus within budget.",
  ui_story_5025_50253301_274_dialog_content = "I do blow through money sometimes. I appreciate you holding me accountable.",
  ui_story_5025_50253301_275_dialog_content = "Heheh. Looks like I've got one more good thing to add to today's diary entry.",
  ui_story_5025_50253301_276_dialog_content = "Hold on. Where's your message for me?",
  ui_story_5025_50253301_277_dialog_content = "I don't see \"what Vice wants to tell PlayerName the most\" anywhere.",
  ui_story_5025_50253301_278_dialog_content = "Hmm? You have my entire diary now. Don't you understand?",
  ui_story_5025_50253301_279_dialog_content = "This diary is what I want you to know!",
  ui_story_5025_50253301_280_dialog_content = "Take it, and read it in your own time.",
  ui_story_5025_50253301_281_dialog_content = "I-It's for me?",
  ui_story_5025_50253301_282_dialog_content = "Yes, and you can't give it back!",
  ui_story_5025_50253301_283_dialog_content = "One more thing. I want you to write the last line in this diary...",
  ui_story_5025_50253301_284_dialog_content = "Me?",
  ui_story_5025_50253301_285_dialog_content = "Yes! After all, this is a diary about you!",
  ui_story_5025_50253301_286_dialog_content = "I want you to finish it.",
  ui_story_5025_50253301_287_dialog_content = "Looking back on our journey, what would you like to say?",
  ui_story_5025_50253301_288_dialog_content = "Take your time... Think about it and write when you're ready.",
  ui_story_5025_50253301_289_dialog_content = "I'll always be here waiting for you..."
}
return config
